                "FROM reservations r " +
                "JOIN rooms room ON r.room_number = room.number " +
                "WHERE r.status IN ('CONFIRMED', 'CHECKED_IN', 'CHECKED_OUT') " +
                "AND r.check_in <= '%s' " +
